<script setup>
import {computed,ref} from 'vue';
import {FormKitSchema} from '@formkit/vue';
import IconButton from './IconButton.vue';
import CodeEditor from './CodeEditor.vue';
import AgeKeyField from './AgeKeyField.vue';
import ProcessorEditor from './ProcessorEditor.vue';
const props=defineProps({kind:String,item:Object,sources:{type:Array,default:()=>[]}});const emit=defineEmits(['save','cancel','logs','preview']);
const clone=x=>JSON.parse(JSON.stringify(x));
const draft=ref({name:'',displayName:'',remark:'',tag:'',icon:'',isIconColor:false,iconFit:'contain',source:'remote',sourceType:'remote',url:'',content:'',noCache:false,passThroughUA:false,noFlow:false,firstSubFlow:false,ua:'',subUserinfo:'',proxy:'',mergeSources:'',subscriptions:[],subscriptionTags:[],type:props.kind==='editor'?'file':'subscription',mode:'config',download:false,includeUnsupportedProxy:false,subInfoUrl:'',subInfoUserAgent:'','age-public-key':'',ignoreFailedRemoteSub:'disabled',ignoreFailedRemoteFile:'disabled',upload:true,cron:'',prettyYaml:false,platform:'Stash',token:'',expiresValue:1,expiresUnit:'month',expirationMode:'duration',usedCount:0,process:[],quick:{},...clone(props.item||{})});
if(props.kind==='sub'){draft.value.type=props.item?.type==='collection'?'collection':'subscription';draft.value.source=props.item?.type==='local'?'local':'remote';draft.value.subscriptions=props.item?.subscriptions||props.item?.members||[]}
if(props.kind==='share')draft.value.sourceType=({sub:'subscription',col:'collection',file:'file'})[props.item?.type]||props.item?.sourceType||'subscription';
if(props.kind==='editor'){draft.value.outputCategory=props.item?.type||'config';draft.value.type=props.item?.fileType||'file';draft.value.sourceType=props.item?.type==='nodes'?'subscription':draft.value.sourceType}
const tab=ref('source');const status=ref('');const memberQuery=ref('');const fileMode=computed(()=>props.kind==='editor');const subMode=computed(()=>props.kind==='sub');const collection=computed(()=>subMode.value&&draft.value.type==='collection');const remote=computed(()=>fileMode.value?draft.value.sourceType==='remote':draft.value.source==='remote');
const tabs=computed(()=>[['source','来源与内容'],['display','显示信息'],...(['editor','sub'].includes(props.kind)?[['request','请求与输出'],['process','加工链']]:[])]);
const field=(name,label,type='text',extra={})=>({$formkit:type,name,label,preserve:true,...extra});
const common=[field('displayName','显示名称'),field('remark','备注','textarea'),field('tag','标签'),field('icon','图标地址','text',{help:'可使用图标地址或表情符号。'}),field('isIconColor','使用图标原始颜色','checkbox'),field('iconFit','图标填充','select',{options:{contain:'完整显示',cover:'填满裁切',fill:'拉伸填满','scale-down':'按需缩小',none:'原始大小'}})];
const quickOptions=[['useless','移除无用节点'],['udp','UDP'],['scert','跳过证书验证'],['tfo','TCP Fast Open'],['vmess aead','VMess AEAD'],['reuse','连接复用'],['block-quic','阻止 QUIC'],['ecn','ECN'],['ip-version','IP 版本偏好']];
const sourceChoices=computed(()=>props.sources.filter(s=>draft.value.sourceType==='collection'?s.resourceKind==='sub'&&s.type==='collection':draft.value.sourceType==='file'?s.resourceKind==='file':s.resourceKind==='sub'&&s.type!=='collection').map(s=>({label:s.displayName||s.name,value:s.name})));
const members=computed(()=>props.sources.filter(s=>s.resourceKind==='sub'&&s.type!=='collection'&&s.name.toLowerCase().includes(memberQuery.value.toLowerCase())).map(s=>({label:s.displayName||s.name,value:s.name})));
function save(values){if(!draft.value.name.trim()){tab.value='display';status.value='请填写名称';return}if(subMode.value&&!collection.value&&remote.value&&!draft.value.url.trim()){tab.value='source';status.value='请填写订阅地址';return}if(remote.value&&draft.value.url&&draft.value.url.split('\n').some(url=>{try{return !['http:','https:'].includes(new URL(url).protocol)}catch{return true}})){tab.value='source';status.value='订阅地址必须是 HTTP 或 HTTPS 地址，每行一个';return}emit('save',clone(draft.value))}
function selectAll(){draft.value.subscriptions=members.value.map(s=>s.value)}
function moveMember(i,delta){const array=draft.value.subscriptions;const j=i+delta;if(j>=0&&j<array.length)array.splice(j,0,array.splice(i,1)[0])}
</script>
<template><FormKit type="form" v-model="draft" :actions="false" :incomplete-message="false" class="resource-editor" @submit="save"><FormKit v-model="draft.name" name="name" label="名称" validation="required" preserve/><div class="resource-tabs" role="tablist" aria-label="编辑分类"><button v-for="[key,label] in tabs" :key="key" type="button" class="filter" role="tab" :aria-selected="tab===key" :class="{selected:tab===key}" @click="tab=key">{{label}}</button></div><p v-if="status" class="resource-status" role="alert">{{status}}</p>
<section v-show="tab==='display'"><FormKitSchema :schema="common"/></section>
<section v-show="tab==='source'">
<template v-if="subMode"><FormKit v-model="draft.type" name="type" label="订阅类型" type="select" :options="{subscription:'单订阅',collection:'组合订阅'}"/><FormKit v-if="!collection" v-model="draft.source" name="source" label="订阅来源" type="select" :options="{remote:'远程订阅',local:'本地节点'}"/><template v-else><FormKit v-model="draft.subscriptionTags" name="subscriptionTags" type="checkbox" label="按标签自动选择" :options="[...new Set(sources.map(s=>s.tag).filter(Boolean))]"/><FormKit v-model="memberQuery" :ignore="true" type="search" label="搜索可选订阅"/><button type="button" class="button" @click="selectAll">选择筛选结果</button><FormKit v-model="draft.subscriptions" name="subscriptions" label="手动选择订阅" type="checkbox" :options="members"/><div v-for="(name,index) in draft.subscriptions" :key="name" class="resource-row"><span>{{name}}</span><IconButton label="向上移动来源" icon="faArrowUp" :disabled="index===0" @activate="moveMember(index,-1)"/><IconButton label="向下移动来源" icon="faArrowDown" :disabled="index===draft.subscriptions.length-1" @activate="moveMember(index,1)"/></div></template></template>
<template v-if="fileMode"><FormKit v-model="draft.outputCategory" name="outputCategory" type="select" label="文件分类" :options="{config:'完整配置',nodes:'节点文件',local:'普通文件'}"/><FormKit v-model="draft.type" name="type" type="select" label="文件类型" :options="{file:'普通文件',mihomoConfig:'mihomo 配置'}"/><FormKit v-model="draft.sourceType" name="sourceType" type="select" label="内容来源" :options="{subscription:'单订阅',collection:'组合订阅',remote:'远程文件',local:'本地内容',none:'无初始内容'}"/><template v-if="['subscription','collection'].includes(draft.sourceType)"><FormKit v-model="draft.sourceName" name="sourceName" type="select" label="选择订阅" :options="sourceChoices"/><FormKit v-model="draft.mode" name="mode" type="select" label="生成内容" :options="{config:'完整配置',proxies:'节点列表'}"/><FormKit v-model="draft.includeUnsupportedProxy" name="includeUnsupportedProxy" type="checkbox" label="包含不支持的节点"/></template><FormKit v-model="draft.download" name="download" type="checkbox" label="下载为文件"/></template>
<template v-if="(subMode&&!collection&&remote)||(fileMode&&draft.sourceType==='remote')"><FormKit v-model="draft.url" name="url" type="textarea" :label="subMode?'订阅地址':'远程文件地址'" help="每行一个 HTTP 或 HTTPS 地址。" validation="required" preserve/><a v-if="draft.url&&draft.url.startsWith('https://')&&!draft.url.includes('\n')" class="card-link" :href="draft.url" target="_blank" rel="noopener">打开来源 ↗</a></template>
<template v-if="(subMode&&!collection&&!remote)||(fileMode&&draft.sourceType==='local')"><h3>{{subMode?'节点内容':'文件内容'}}</h3><CodeEditor v-model="draft.content" :language="subMode?'text':'yaml'"/></template>
<template v-if="kind==='sync'||kind==='share'"><FormKit v-model="draft.sourceType" name="sourceType" label="来源类型" type="select" :options="{subscription:'单订阅',collection:'组合订阅',file:'文件'}"/><FormKit v-model="draft.sourceName" name="sourceName" label="选择来源" type="select" :options="sourceChoices"/><AgeKeyField v-model="draft['age-public-key']"/><a href="https://github.com/sub-store-org/Sub-Store/wiki/链接参数说明" class="card-link" target="_blank" rel="noopener">加密与链接参数说明 ↗</a></template>
<template v-if="kind==='sync'"><FormKit v-model="draft.upload" name="upload" type="checkbox" label="启用上传"/><FormKit v-model="draft.cron" name="cron" label="定时表达式" placeholder="0 0 * * *"/><FormKit v-if="draft.sourceType!=='file'" v-model="draft.platform" name="platform" type="select" label="输出客户端" :options="['Stash','Egern','ClashMeta','Surfboard','Surge','SurgeMac','Loon','ShadowRocket','QX','sing-box','V2Ray','URI','JSON','Clash']"/><FormKit v-model="draft.includeUnsupportedProxy" name="includeUnsupportedProxy" type="checkbox" label="包含不支持的节点"/><FormKit v-model="draft.prettyYaml" name="prettyYaml" type="checkbox" label="美化 YAML 输出"/></template>
<template v-if="kind==='share'"><FormKit v-model="draft.token" name="token" label="分享 Token" help="留空时在正式服务中生成；设计稿只使用示例值。"/><FormKit v-model="draft.expirationMode" name="expirationMode" type="select" label="有效期方式" :options="{duration:'有效时长',datetime:'指定到期时间',count:'使用次数'}"/><template v-if="draft.expirationMode==='duration'"><FormKit v-model="draft.expiresUnit" name="expiresUnit" type="select" label="有效期单位" :options="{day:'天',month:'月',season:'季度',year:'年',lifetime:'永久'}"/><FormKit v-if="draft.expiresUnit!=='lifetime'" v-model="draft.expiresValue" name="expiresValue" type="number" label="有效期数值" min="1" validation="min:1"/></template><FormKit v-if="draft.expirationMode==='datetime'" v-model="draft.exactDatetime" name="exactDatetime" type="datetime-local" label="到期时间"/><template v-if="draft.expirationMode==='count'"><FormKit v-model="draft.count" name="count" type="number" min="1" validation="min:1" label="允许使用次数"/><FormKit v-model="draft.usedCount" name="usedCount" type="number" min="0" label="已使用次数"/></template><p class="field-note">永久有效期需要后端 ≥ 2.42.5，指定到期时间需要 ≥ 2.22.6。</p></template></section>
<section v-show="tab==='request'" v-if="subMode||fileMode"><template v-if="!collection"><FormKit v-model="draft.noCache" name="noCache" type="checkbox" label="不使用缓存"/><FormKit v-if="subMode" v-model="draft.passThroughUA" name="passThroughUA" type="checkbox" label="透传客户端 User-Agent"/><FormKit v-model="draft.ua" name="ua" label="请求 User-Agent"/><FormKit v-model="draft.mergeSources" name="mergeSources" type="select" label="合并多个来源" :options="{'':'不合并',localFirst:'本地优先',remoteFirst:'远程优先'}"/><FormKit :model-value="fileMode?draft.ignoreFailedRemoteFile:draft.ignoreFailedRemoteSub" :name="fileMode?'ignoreFailedRemoteFile':'ignoreFailedRemoteSub'" @input="fileMode?draft.ignoreFailedRemoteFile=$event:draft.ignoreFailedRemoteSub=$event" type="select" label="远程来源失败策略" :options="fileMode?{disabled:'中断处理',enabled:'忽略失败并通知',quiet:'忽略失败并静默'}:{disabled:'中断处理',enabled:'忽略失败并通知',quiet:'忽略失败并静默',fallbackNotify:'回退缓存并通知',fallbackQuiet:'静默回退缓存'}"/></template><FormKit v-model="draft.proxy" name="proxy" label="请求代理／策略"/><FormKit v-if="subMode" v-model="draft.noFlow" name="noFlow" type="checkbox" label="不输出流量信息"/><FormKit v-if="collection" v-model="draft.firstSubFlow" name="firstSubFlow" type="checkbox" label="使用第一个订阅流量"/><FormKit v-if="subMode" v-model="draft.subUserinfo" name="subUserinfo" label="自定义流量信息"/><template v-if="fileMode"><FormKit v-model="draft.subInfoUrl" name="subInfoUrl" label="流量信息地址"/><FormKit v-model="draft.subInfoUserAgent" name="subInfoUserAgent" label="流量信息 User-Agent"/></template><AgeKeyField v-model="draft['age-public-key']"/><a class="card-link" href="https://github.com/sub-store-org/Sub-Store/wiki/链接参数说明" target="_blank" rel="noopener">公钥与加密说明 ↗</a><template v-if="subMode"><h3>常用节点配置</h3><FormKit v-for="[key,label] in quickOptions" :key="key" v-model="draft.quick[key]" :name="'quick-'+key" :ignore="true" :label="label" type="select" :options="key==='ip-version'?{DEFAULT:'保持原值',dual:'双栈','v4-only':'仅 IPv4','v6-only':'仅 IPv6','prefer-v4':'优先 IPv4','prefer-v6':'优先 IPv6'}:['block-quic','ecn'].includes(key)?{DEFAULT:'保持原值',auto:'自动',on:'开启',off:'关闭'}:{DEFAULT:'保持原值',ENABLED:'启用',DISABLED:'禁用'}"/></template></section>
<section v-show="tab==='process'" v-if="subMode||fileMode"><ProcessorEditor v-model="draft.process" :file="fileMode" :sources="sources" @preview="emit('preview',{...draft,step:$event})"/></section>
<p class="field-note">示例数据仅保存在当前浏览器；不连接真实后端。</p><footer class="dialog-actions"><IconButton label="查看 Sub-Store 日志" icon="faTerminal" @activate="emit('logs',draft)"/><IconButton v-if="subMode||fileMode" label="预览处理结果" icon="faEye" @activate="emit('preview',draft)"/><button type="button" class="button" @click="emit('cancel')">取消</button><button type="submit" class="button primary">保存更改</button></footer></FormKit></template>
